import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';
import tsconfigPaths from 'vite-tsconfig-paths';
import type { Plugin as PostcssPlugin, Rule } from 'postcss';
import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
import type { Plugin } from 'vite';

/**
 * Staging only: recolor the staging (orange) palette pink while the
 * testnet API is selected. Every declaration that uses a staging-only
 * color (src/assets/testnet-palette.json, generated by
 * scripts/gen-testnet-palette.mjs) gets a pink twin scoped to
 * html[data-vx-cluster="testnet"] - set by helpers/apiEndpoint at load.
 * Covers Bootstrap's baked-in literals too, which CSS variables can't.
 */
const testnetPalette = (): PostcssPlugin => {
  const map: Record<string, string> = JSON.parse(
    readFileSync('src/assets/testnet-palette.json', 'utf8')
  );
  const ATTR = '[data-vx-cluster="testnet"]';
  const recolor = (value: string) =>
    value
      .replace(
        /#([0-9a-fA-F]{6})\b/g,
        (m, h) => map['#' + h.toLowerCase()] ?? m
      )
      .replace(
        /(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)/g,
        (m, a, b, c) => map[`${a},${b},${c}`]?.replace(/,/g, ', ') ?? m
      );
  // Put the attribute on <html>: on the selector's first compound when it
  // already targets the root (:root, html, [data-bs-theme...]), else as an
  // ancestor.
  const scope = (sel: string) => {
    const t = sel.trim();
    const m = t.match(/^(:root|html)?((?:\[[^\]]+\])*)/);
    if (m && (m[1] || m[2].startsWith('[data-bs-theme')))
      return m[0] + ATTR + t.slice(m[0].length);
    return `html${ATTR} ${t}`;
  };
  return {
    postcssPlugin: 'vx-testnet-palette',
    OnceExit(root) {
      const twins: Array<[Rule, Rule]> = [];
      root.walkRules(rule => {
        const parent = rule.parent;
        if (parent?.type === 'atrule' && /keyframes/.test((parent as any).name))
          return;
        const changed = rule.nodes.filter(
          n => n.type === 'decl' && recolor(n.value) !== n.value
        );
        if (!changed.length) return;
        const twin = rule.clone({ nodes: [] });
        twin.selectors = rule.selectors.map(scope);
        for (const d of changed)
          if (d.type === 'decl')
            twin.append(d.clone({ value: recolor(d.value) }));
        twins.push([rule, twin]);
      });
      for (const [rule, twin] of twins) rule.after(twin);
    }
  };
};

/**
 * Stamps the commit a build came from into index.html
 * (<meta name="vx-build" content="<sha>">), so which commit each site
 * serves - and when a deploy landed - is visible with a curl. CI's
 * GITHUB_SHA, else the checkout's HEAD.
 */
const gitSha = () => {
  if (process.env.GITHUB_SHA) return process.env.GITHUB_SHA;
  try {
    return execSync('git rev-parse HEAD').toString().trim();
  } catch {
    return 'unknown';
  }
};

const buildStamp = (sha: string): Plugin => {
  return {
    name: 'vx-build-stamp',
    transformIndexHtml: html =>
      html.replace(
        '</head>',
        `  <meta name="vx-build" content="${sha.slice(0, 12)}" />\n  </head>`
      )
  };
};

export default defineConfig(({ mode }) => {
  // Same VITE_DEPLOY_ENV the app reads, handed to SCSS so the staging build
  // compiles with an orange primary palette (see _user-variables.scss).
  // Build time, because Bootstrap bakes $primary into literal values (button
  // backgrounds etc.) that a runtime CSS-variable override can't reach.
  const deployEnv = loadEnv(mode, process.cwd(), 'VITE_').VITE_DEPLOY_ENV ?? '';
  // testnet.vx.tools is the staging palette recolored pink: compile the
  // staging (orange) SCSS and add the pink twins, which apply under
  // html[data-vx-cluster="testnet"] (set at load for that build).
  const scssEnv = deployEnv === 'testnet' ? 'staging' : deployEnv;
  const sha = gitSha();
  return {
    plugins: [tsconfigPaths(), react(), buildStamp(sha)],
    // The same commit, for the staging navbar's build link.
    define: { __VX_BUILD__: JSON.stringify(sha) },
    css: {
      postcss:
        scssEnv === 'staging' ? { plugins: [testnetPalette()] } : undefined,
      preprocessorOptions: {
        scss: {
          api: 'modern-compiler',
          additionalData: `$vx-deploy-env: '${scssEnv}';\n`,
          // Suppress deprecation warnings originating from Bootstrap's own SCSS
          // (legacy @import, color functions, global builtins); our theme
          // imports Bootstrap the same way until it moves to @use/@forward.
          silenceDeprecations: [
            'import',
            'global-builtin',
            'color-functions',
            'slash-div',
            'if-function'
          ]
        }
      }
    },
    server: {
      port: 3000,
      open: false
    },
    preview: {
      port: 3000
    },
    build: {
      outDir: 'build',
      sourcemap: true
    }
  };
});
